-- Project Ambrose by Imjustchico
-- Adds the behavior_client_class rows every other template placed in a zone needs, found by reading each placed template's behaviors and following each name to the factory the r806919 client program registers for it: the class the factory builds, or an empty slot where the program holds no string of that name to register one under.
ON DUPLICATE KEY UPDATE `class_name` = VALUES(`class_name`), `evidence` = VALUES(`evidence`);
